93	/** Run `paint(set)` twice: as written, and mirrored across x = cx (x' = 2cx - x), flipping east/west facings. */
94	export function mirrorX(g, cx, paint) {
95	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
96	  paint((x, y, z, block, state) => g.set(2 * cx - x, y, z, block, state && state.facing ? { ...state, facing: face.mirrorX(state.facing) } : state));
97	}
98	export function mirrorZ(g, cz, paint) {
99	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
100	  paint((x, y, z, block, state) => g.set(x, y, 2 * cz - z, block, state && state.facing ? { ...state, facing: face.mirrorZ(state.facing) } : state));
101	}
