103	/** Hollow box: walls (and optional floor/ceiling) of a cuboid. */
104	export function shell(g, a, b, block, { floor = true, ceiling = true, state } = {}) {
105	  const [x0, y0, z0] = a.map((v, i) => Math.min(v, b[i])), [x1, y1, z1] = a.map((v, i) => Math.max(v, b[i]));
106	  for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) {
107	    const edge = x === x0 || x === x1 || z === z0 || z === z1 || (floor && y === y0) || (ceiling && y === y1);
108	    if (edge) g.set(x, y, z, block, state);
109	  }
110	}
