115	/** Replace only where the current block matches `from` (a name or a predicate). */
116	export function replace(g, a, b, from, block, state) {
117	  const match = typeof from === "function" ? from : (n) => n === ns(from);
118	  for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
119	    for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
120	      for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) if (match(g.blockAt(x, y, z))) g.set(x, y, z, block, state);
121	}
