123	/**
124	 * Wrap a grid so writes into protected cells are refused (counted, never thrown), so a decor script cannot
125	 * break function. protect: Set of "x,y,z" — default: the grid's own functional cells and the cells that must stay
126	 * clear around them (check.mjs functionalCells). `g.refused` lists what was blocked; report it.
127	 */
128	export function guard(g, protect) {
129	  const cells = protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
130	  const refused = [];
131	  return new Proxy(g, {
132	    get(target, prop) {
133	      if (prop === "refused") return refused;
134	      if (prop === "protected") return cells;
135	      if (prop === "set") return (x, y, z, ...rest) => { if (cells.has(`${x},${y},${z}`)) { refused.push([x, y, z, rest[0]]); return target; } return target.set(x, y, z, ...rest); };

